// The webhook keeps the exact bytes the site signed (Options -> Raw Body), so the signature is checked on those bytes.
const item = $input.first();
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const text = raw.toString('utf8');
const signature = String((item.json.headers || {})['x-syncflow-signature'] || '');
let body;
try {
  body = JSON.parse(text);
} catch (error) {
  throw new Error('the body is not JSON');
}
return [{ json: { ...body, _raw: text, _signature: signature } }];

